ALTER TABLE users MODIFY role ENUM('admin','organizer','witness','voter') NOT NULL;
CREATE TABLE IF NOT EXISTS election_witnesses (election_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,assigned_by BIGINT UNSIGNED NOT NULL,assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(election_id,user_id),CONSTRAINT fk_ew_election FOREIGN KEY(election_id) REFERENCES elections(id) ON DELETE CASCADE,CONSTRAINT fk_ew_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_ew_assigner FOREIGN KEY(assigned_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS witness_checkpoints (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,election_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,stage ENUM('setup_reviewed','census_verified','opening_attested','closing_attested','results_attested') NOT NULL,snapshot_json JSON NOT NULL,sha256_hash CHAR(64) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_wc_election(election_id,created_at),CONSTRAINT fk_wc_election FOREIGN KEY(election_id) REFERENCES elections(id) ON DELETE CASCADE,CONSTRAINT fk_wc_user FOREIGN KEY(user_id) REFERENCES users(id));
